package dev.zomboid.installer;
import java.io.*;import java.nio.file.*;import java.time.*;import java.time.format.*;
public final class Diagnostics {
 private final Path folder,log;private String lastError="";private String report="Todavía no se ha revisado una instalación.";
 public Diagnostics(Path home)throws IOException{Path f=home.resolve("logs");try{Files.createDirectories(f);}catch(IOException e){f=Path.of(System.getProperty("java.io.tmpdir"),"Zombies-Poldo-logs");Files.createDirectories(f);}folder=f;log=f.resolve("sesion-"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss"))+".log");event("Inicio · Java "+System.getProperty("java.version")+" · "+System.getProperty("os.name")+" "+System.getProperty("os.arch"));}
 public Path folder(){return folder;}public Path log(){return log;}public synchronized String report(){return report+(lastError.isEmpty()?"":"\nÚLTIMO ERROR\n"+lastError);}
 public synchronized void event(String text){try{Files.writeString(log,LocalDateTime.now()+" | "+text+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(IOException e){System.err.println("No se pudo escribir el log: "+e.getMessage());}}
 public synchronized void error(String operation,Throwable error){StringWriter sw=new StringWriter();error.printStackTrace(new PrintWriter(sw));lastError=operation+"\n"+sw;event(lastError);}
 public synchronized void review(Engine.Plan plan){StringBuilder s=new StringBuilder("ZOMBIES POLDO · DIAGNÓSTICO\n");s.append("Fecha: ").append(LocalDateTime.now()).append("\nInstancia: ").append(plan.instance()).append("\nPack: ").append(plan.pack().name()).append("\nMinecraft: ").append(plan.pack().minecraft()).append(" · NeoForge: ").append(plan.pack().neoForge()).append("\n\nPROBLEMAS POR RESOLVER\n");long errors=plan.checks().stream().filter(c->!c.good()).count();s.append(errors).append(" problemas; ").append(plan.copies().size()).append(" archivos para copiar.\n");for(Engine.Check c:plan.checks())if(!c.good())s.append("\n[").append(c.group()).append("] ").append(c.title()).append("\n").append(c.detail()).append("\n");s.append("\nTODAS LAS COMPROBACIONES\n");for(Engine.Check c:plan.checks())s.append(c.good()?"OK | ":"ERROR | ").append(c.group()).append(" | ").append(c.title()).append(" | ").append(c.detail()).append("\n");report=s.toString();event(report);try{save(folder.resolve("ultimo-diagnostico.txt"));}catch(IOException e){error("Guardar diagnóstico",e);}}
 public synchronized void save(Path target)throws IOException{Files.writeString(target,report()+"\nLog de sesión: "+log+"\n");}
}
